begin;
create extension if not exists pgtap with schema extensions;
select plan(35);
select set_config('test.agent_company',gen_random_uuid()::text,true);
select set_config('test.agent_one',gen_random_uuid()::text,true);
select set_config('test.agent_two',gen_random_uuid()::text,true);
insert into public.companies(id,slug,name) values (current_setting('test.agent_company')::uuid,'agent-role-test','Test');
insert into auth.users(id,email) values (current_setting('test.agent_one')::uuid,'returning-agent@example.test'),(current_setting('test.agent_two')::uuid,'replacement-agent@example.test');
insert into public.people(id,name) values (current_setting('test.agent_one')::uuid,'Agent with a different id'),(current_setting('test.agent_two')::uuid,'Another agent');
insert into public.members(company_id,person_id,role) values
 (current_setting('test.agent_company')::uuid,'20000000-0000-0000-0000-000000000001','owner'),
 (current_setting('test.agent_company')::uuid,current_setting('test.agent_one')::uuid,'contributor'),
 (current_setting('test.agent_company')::uuid,current_setting('test.agent_two')::uuid,'contributor');
set local role authenticated;
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000001',true);
select is((select count(*)::int from public.members where company_id=current_setting('test.agent_company')::uuid and agent_role is null),3,'ordinary members default to no agent role');
select lives_ok($$update public.members set agent_role='writer' where company_id=current_setting('test.agent_company')::uuid and person_id=current_setting('test.agent_one')::uuid$$,'owner assigns a stable key to an arbitrary person id');
select is((select before_data->>'agent_role' from public.member_audit where company_id=current_setting('test.agent_company')::uuid and action='UPDATE' order by id desc limit 1),null::text,'audit snapshots the old key');
select is((select after_data->>'agent_role' from public.member_audit where company_id=current_setting('test.agent_company')::uuid and action='UPDATE' order by id desc limit 1),'writer','audit snapshots the new key');
select throws_ok($$update public.members set agent_role='advertiser' where company_id=current_setting('test.agent_company')::uuid and person_id=current_setting('test.agent_two')::uuid$$,'22P02',null,'unsupported key is rejected');
select throws_ok($$update public.members set agent_role='writer' where company_id=current_setting('test.agent_company')::uuid and person_id=current_setting('test.agent_two')::uuid$$,'23505',null,'active keys are unique within a company');
select throws_ok($$update public.members set agent_role='designer' where company_id=current_setting('test.agent_company')::uuid and role='owner'$$,'23514',null,'owner cannot hold an agent key');
select throws_ok($$update public.members set role='manager' where company_id=current_setting('test.agent_company')::uuid and agent_role='writer'$$,'23514',null,'manager cannot hold an agent key');
select throws_ok($$update public.members set role='reviewer' where company_id=current_setting('test.agent_company')::uuid and agent_role='writer'$$,'22P02',null,'there is no reviewer Role to hold an agent key');
select throws_ok($$update public.members set role='viewer' where company_id=current_setting('test.agent_company')::uuid and agent_role='writer'$$,'23514',null,'viewer cannot hold an agent key');
select lives_ok($$insert into public.members(company_id,person_id,role,agent_role) values ('10000000-0000-0000-0000-000000000003',current_setting('test.agent_one')::uuid,'contributor','writer')$$,'the same key is allowed in another company');
select lives_ok($$select public.remove_member(current_setting('test.agent_company')::uuid,current_setting('test.agent_one')::uuid)$$,'key holder can be removed');
select lives_ok($$update public.members set agent_role='writer' where company_id=current_setting('test.agent_company')::uuid and person_id=current_setting('test.agent_two')::uuid$$,'removed key can be assigned to a replacement');
reset role;
select throws_ok($$update public.members set removed_at=null where company_id=current_setting('test.agent_company')::uuid and person_id=current_setting('test.agent_one')::uuid$$,'23505',null,'restoring a conflicting holder is rejected');
set local role authenticated;
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000001',true);
insert into public.member_invitations(company_id,email,role) values (current_setting('test.agent_company')::uuid,'returning-agent@example.test','contributor');
select set_config('request.jwt.claim.sub',current_setting('test.agent_one'),true);
select lives_ok($$select public.claim_invitations()$$,'removed agent can reclaim an invitation while a replacement holds its old key');
select is(public.is_member(current_setting('test.agent_company')::uuid),true,'claim reactivates the removed member');
select is((select agent_role::text from public.members where company_id=current_setting('test.agent_company')::uuid and person_id=auth.uid()),null::text,'claim clears the stale agent key');
select is((select role::text from public.members where company_id=current_setting('test.agent_company')::uuid and person_id=auth.uid()),'contributor','claim applies the invitation role');
select is((select agent_role::text from public.members where company_id=current_setting('test.agent_company')::uuid and person_id=current_setting('test.agent_two')::uuid),'writer','claim keeps the replacement key');
select is((select after_data->>'agent_role' from public.member_audit where company_id=current_setting('test.agent_company')::uuid and person_id=auth.uid() and action='UPDATE' order by id desc limit 1),null::text,'claim audits the cleared key');
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000001',true);
select ok((select claimed_at is not null from public.member_invitations where company_id=current_setting('test.agent_company')::uuid and email='returning-agent@example.test'),'claim marks the invitation accepted');
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000004',true);
select is((select count(*)::int from public.members where company_id='10000000-0000-0000-0000-000000000001' and agent_role is not null),4,'viewer can read all four seeded Home role keys');
select is((select count(*)::int from public.members where company_id=current_setting('test.agent_company')::uuid),0,'another company membership stays hidden');
with changed as (update public.members set agent_role=null where company_id='10000000-0000-0000-0000-000000000001' and agent_role is not null returning 1) select is((select count(*)::int from changed),0,'viewer cannot change keys');
select throws_ok($$insert into public.members(company_id,person_id,role,agent_role) values ('10000000-0000-0000-0000-000000000001',current_setting('test.agent_two')::uuid,'contributor','writer')$$,'42501',null,'viewer gains no member insertion path');
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000003',true);
with changed as (update public.members set agent_role=null where company_id='10000000-0000-0000-0000-000000000001' and agent_role is not null returning 1) select is((select count(*)::int from changed),0,'a Contributor cannot change keys');
select set_config('request.jwt.claim.sub',current_setting('test.agent_two'),true);
select is((select agent_role::text from public.members where company_id=current_setting('test.agent_company')::uuid and person_id=auth.uid()),'writer','contributor can read their key');
with changed as (update public.members set agent_role='designer' where company_id=current_setting('test.agent_company')::uuid and person_id=auth.uid() returning 1) select is((select count(*)::int from changed),0,'agent cannot reassign its own key');
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000002',true);
select throws_ok($$update public.members set agent_role=null where company_id='10000000-0000-0000-0000-000000000001' and agent_role='critic'$$,'42501','only an owner can change agent roles','manager cannot clear a Contributor key');
select throws_ok($$update public.members set agent_role='designer' where company_id='10000000-0000-0000-0000-000000000001' and person_id='30000000-0000-0000-0000-000000000004'$$,'42501','only an owner can change agent roles','manager cannot assign an agent key');
select lives_ok($$update public.members set grant_publishing=true where company_id='10000000-0000-0000-0000-000000000001' and agent_role='critic'$$,'manager can still edit keyed member grants');
select lives_ok($$update public.members set role='viewer',agent_role=null where company_id='10000000-0000-0000-0000-000000000001' and agent_role='critic'$$,'manager can release a key when changing the permission role');
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000001',true);
select lives_ok($$update public.members set role='viewer',agent_role=null where company_id=current_setting('test.agent_company')::uuid and person_id=current_setting('test.agent_two')::uuid$$,'owner can clear key when changing the member role');
select is((select after_data->>'agent_role' from public.member_audit where company_id=current_setting('test.agent_company')::uuid and action='UPDATE' order by id desc limit 1),null::text,'audit records key removal');
set local role anon;
select is((select count(*)::int from public.members where agent_role is not null),0,'anonymous cannot read role keys');
select * from finish();
rollback;
